      SUBROUTINE UCTABS (A)      CHARACTER A*(*)C      PARAMETER (IUC=65, ILC=97, ILCL=ILC+25, IDI=IUC-ILC)      CHARACTER TAB*1      DATA      TAB /'	'/C      IF (A .EQ. ' ') RETURNC      LENA = LEN(A)      IF (LENA .LE. 0) GO TO 10      DO I = 1, LENA        IF (A(I:I) .EQ. TAB) THEN          A(I:I) = ' '        ELSE IF (A(I:I) .NE. ' ') THEN          JLC = ICHAR(A(I:I))          IF ((JLC .GE. ILC) .AND. (JLC .LE. ILCL)) THEN            JUC = JLC + IDI            A(I:I) = CHAR(JUC)          ENDIF        ENDIF      END DO   10 RETURN      END